-- Ajouter des colonnes avancées à la table demande_recompense
ALTER TABLE demande_recompense ADD COLUMN IF NOT EXISTS date_approbation DATETIME NULL;
ALTER TABLE demande_recompense ADD COLUMN IF NOT EXISTS date_rejet DATETIME NULL;
ALTER TABLE demande_recompense ADD COLUMN IF NOT EXISTS raison_rejet VARCHAR(500) NULL;
ALTER TABLE demande_recompense ADD COLUMN IF NOT EXISTS approuve_par INT NULL;
ALTER TABLE demande_recompense ADD COLUMN IF NOT EXISTS priorite VARCHAR(50) DEFAULT 'normale' NULL;
ALTER TABLE demande_recompense ADD COLUMN IF NOT EXISTS score_approbation INT DEFAULT 0 NULL;

-- Ajouter des colonnes avancées à la table recompense
ALTER TABLE recompense ADD COLUMN IF NOT EXISTS date_creation DATETIME DEFAULT CURRENT_TIMESTAMP NULL;
ALTER TABLE recompense ADD COLUMN IF NOT EXISTS date_modification DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP NULL;
ALTER TABLE recompense ADD COLUMN IF NOT EXISTS statut_recompense VARCHAR(50) DEFAULT 'active' NULL;
ALTER TABLE recompense ADD COLUMN IF NOT EXISTS cout_estimation INT DEFAULT 0 NULL;

-- Créer la table de notification
CREATE TABLE IF NOT EXISTS notification_recompense (
    id INT AUTO_INCREMENT PRIMARY KEY,
    demande_id INT NOT NULL,
    type_notification VARCHAR(50) NOT NULL,
    statut_notification VARCHAR(50) DEFAULT 'non_lue',
    message TEXT NOT NULL,
    date_creation DATETIME DEFAULT CURRENT_TIMESTAMP,
    date_lecture DATETIME NULL,
    FOREIGN KEY (demande_id) REFERENCES demande_recompense(id) ON DELETE CASCADE
);

-- Créer la table de rapport de statistiques
CREATE TABLE IF NOT EXISTS rapport_recompense (
    id INT AUTO_INCREMENT PRIMARY KEY,
    type_rapport VARCHAR(50) NOT NULL,
    date_debut DATE NOT NULL,
    date_fin DATE NOT NULL,
    total_demandes INT DEFAULT 0,
    total_approuvees INT DEFAULT 0,
    total_rejetees INT DEFAULT 0,
    total_en_attente INT DEFAULT 0,
    cout_total INT DEFAULT 0,
    date_generation DATETIME DEFAULT CURRENT_TIMESTAMP
);

-- Créer la table de règles d'approbation automatique
CREATE TABLE IF NOT EXISTS regle_approbation_auto (
    id INT AUTO_INCREMENT PRIMARY KEY,
    nom_regle VARCHAR(100) NOT NULL,
    description TEXT,
    condition_priorite VARCHAR(50),
    condition_score_min INT DEFAULT 0,
    condition_date_min_jours INT DEFAULT 0,
    action VARCHAR(50) DEFAULT 'approver',
    active BOOLEAN DEFAULT 1,
    date_creation DATETIME DEFAULT CURRENT_TIMESTAMP
);

package edu.connexion3a36.rankup.entities;

import java.time.LocalDateTime;
import java.util.Objects;

public class DemandeRecompense {
    private int id;
    private Integer userId;
    private String nomDemandeur;
    private String email;
    private String motif;
    private LocalDateTime dateDemande;
    private String statut;
    private Integer recompenseId;

    public DemandeRecompense() {
    }

    public DemandeRecompense(String nomDemandeur, String email, String motif, LocalDateTime dateDemande, String statut) {
        this.nomDemandeur = nomDemandeur;
        this.email = email;
        this.motif = motif;
        this.dateDemande = dateDemande;
        this.statut = statut;
    }

    public Integer getUserId() {
        return userId;
    }

    public void setUserId(Integer userId) {
        this.userId = userId;
    }

    public int getId() {
        return id;
    }

    public void setId(int id) {
        this.id = id;
    }

    public String getNomDemandeur() {
        return nomDemandeur;
    }

    public void setNomDemandeur(String nomDemandeur) {
        this.nomDemandeur = nomDemandeur;
    }

    public String getEmail() {
        return email;
    }

    public void setEmail(String email) {
        this.email = email;
    }

    public String getMotif() {
        return motif;
    }

    public void setMotif(String motif) {
        this.motif = motif;
    }

    public LocalDateTime getDateDemande() {
        return dateDemande;
    }

    public void setDateDemande(LocalDateTime dateDemande) {
        this.dateDemande = dateDemande;
    }

    public String getStatut() {
        return statut;
    }

    public void setStatut(String statut) {
        this.statut = statut;
    }

    public Integer getRecompenseId() {
        return recompenseId;
    }

    public void setRecompenseId(Integer recompenseId) {
        this.recompenseId = recompenseId;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        DemandeRecompense that = (DemandeRecompense) o;
        return id == that.id;
    }

    @Override
    public int hashCode() {
        return Objects.hash(id);
    }

    @Override
    public String toString() {
        return "DemandeRecompense{" +
                "id=" + id +
                ", nomDemandeur='" + nomDemandeur + '\'' +
                ", email='" + email + '\'' +
                ", motif='" + motif + '\'' +
                ", dateDemande=" + dateDemande +
                ", statut='" + statut + '\'' +
                ", recompenseId=" + recompenseId +
                '}';
    }
}

